document.addEventListener('DOMContentLoaded', () => {
    const form = document.getElementById('consent-form');
    const checkbox = document.getElementById('terms-consent');
    const errorMsg = document.getElementById('terms-error');
    const statusRegion = document.getElementById('status-region');

    form.addEventListener('submit', (event) => {
        event.preventDefault();

        // Reset state
        errorMsg.hidden = true;
        checkbox.setAttribute('aria-invalid', 'false');
        statusRegion.textContent = '';
        statusRegion.className = 'status-message';

        if (!checkbox.checked) {
            // Invalid state
            errorMsg.hidden = false;
            checkbox.setAttribute('aria-invalid', 'true');
            checkbox.focus();
        } else {
            // Valid state - simulated success
            statusRegion.textContent = 'Account created successfully!';
            statusRegion.classList.add('success');

            // Optionally reset form
            // form.reset();
        }
    });

    // Clear error as soon as user checks the box
    checkbox.addEventListener('change', () => {
        if (checkbox.checked) {
            errorMsg.hidden = true;
            checkbox.setAttribute('aria-invalid', 'false');
        }
    });
});

